const boardsList = `-- name: BoardsList :many
SELECT id, slug, name, description, creator_id, post_count, last_activity_at, created_at, deleted_at FROM boards
WHERE deleted_at IS NULL
  AND (NOT $2::bool OR last_activity_at < $3 OR (last_activity_at = $3 AND id < $4))
ORDER BY last_activity_at DESC, id DESC
LIMIT $1
`

type BoardsListParams struct {
	Limit     int32
	HasCursor bool
	CursorAt  time.Time
	CursorID  uuid.UUID
}

func (q *Queries) BoardsList(ctx context.Context, arg BoardsListParams) ([]Board, error) {
	rows, err := q.db.Query(ctx, boardsList,
		arg.Limit,
		arg.HasCursor,
		arg.CursorAt,
		arg.CursorID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Board{}
	for rows.Next() {
		var i Board
		if err := rows.Scan(
			&i.ID,
			&i.Slug,
			&i.Name,
			&i.Description,
			&i.CreatorID,
			&i.PostCount,
			&i.LastActivityAt,
			&i.CreatedAt,
			&i.DeletedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
